 <script>
+(()=>{
+const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');const overlay=document.getElementById('overlay'),startBtn=document.getElementById('start');const coinLabel=document.getElementById('coins'),lifeLabel=document.getElementById('lives'),hint=document.getElementById('hint');
