+const platforms=[{x:0,y:0,z:0,w:14,d:12},{x:17,y:0,z:0,w:11,d:8},{x:31,y:0,z:0,w:13,d:12},{x:47,y:0,z:0,w:13,d:10},{x:63,y:0,z:0,w:17,d:12},{x:12,y:2.2,z:-1,w:3,d:3},{x:25,y:2.5,z:1,w:3,d:3},{x:40,y:2.1,z:-2,w:3,d:3},{x:56,y:2.4,z:2,w:3,d:3}];
